@Component
public class TelemetryConsumer {
    @Autowired private DatabaseService db;

    @KafkaListener(topics = "telemetry-events", groupId = "telemetry-processor")
    public void listen(List<ConsumerRecord<String, byte[]>> records, Acknowledgment ack) {
        // BUG: Heavy synchronous database write inside poll loop blocks the consumer thread,
        // causing max.poll.interval.ms (default 300s) to be exceeded during spikes
        for (ConsumerRecord<String, byte[]> r : records) {
            db.heavyPersist(r.value());
        }
        ack.acknowledge();
    }
}

